from __future__ import annotations

import inspect
import re
import sys
import traceback
from pathlib import Path

import bench.cdsfl_registry.composer as composer


def _main() -> None:
    # 1. Read real code via inspect.
    compose_source = inspect.getsource(composer.compose)

    if "_apply_phenotype_transform" not in compose_source:
        # No target path in this version; finding is absent.
        return

