        layer="domain",
        name="falsifier-hard-domain",
        text=(
            "# HARD Domain Rule\n"
            "This HARD domain directive must preserve its example and rationale.\n"
            "Example:\n"
            "DO_NOT_STRIP_THIS_HARD_DOMAIN_EXAMPLE\n"
            "---\n"
            "Why: DO_NOT_STRIP_THIS_HARD_DOMAIN_RATIONALE\n"
            "Final HARD domain sentence."
        ),
        constraint_class="HARD",
        domain="falsifier_domain",
        tags={"falsifier"},
    )

    hard_situation = DirectivePacket(
        layer="situation",
        name="falsifier-hard-situation",
        text=(
            "# HARD Situation Rule\n"
            "This HARD situation directive must preserve its example and rationale.\n"
            "Example:\n"
            "DO_NOT_STRIP_THIS_HARD_SITUATION_EXAMPLE\n"
            "---\n"
            "Why: DO_NOT_STRIP_THIS_HARD_SITUATION_RATIONALE\n"
            "Final HARD situation sentence."
        ),
        constraint_class="HARD",
        domain="falsifier_domain",
        tags={"falsifier"},
    )

    universal = DirectivePacket(
        layer="universal",
        name="falsifier-universal",
        text="Universal packet used only to let compose() run.",
        constraint_class="SOFT",
        tags={"falsifier"},
    )

    phenotype = DirectivePacket(
        layer="phenotype",
        name="falsifier-phenotype",
        text="Phenotype packet used only to let compose() run.",
        constraint_class="SOFT",
        model="codex_5_3",
        tags={"falsifier"},
    )

    # 2. Snapshot before the in-place-mutating compose() call.
    before = {
        hard_domain.name: hard_domain.text,
        hard_situation.name: hard_situation.text,
    }

