    def patch(name: str, value: object) -> None:
        if hasattr(composer, name):
            originals[name] = getattr(composer, name)
            setattr(composer, name, value)

    def returns_sequence(name: str) -> bool:
        return bool(
            re.search(r"\.extend\s*\(\s*" + re.escape(name) + r"\s*\(", compose_source)
            or re.search(r"\bfor\s+\w+\s+in\s+" + re.escape(name) + r"\s*\(", compose_source)
        )

    def loader_return(name: str, packet: object):
        if returns_sequence(name):
            return [packet]
        return packet

    def make_packet_loader(name: str, packet: object):
        def _loader(*args, **kwargs):
            return loader_return(name, packet)

        return _loader

    def make_generic_directive_loader(name: str):
        def _loader(*args, **kwargs):
