            return "codex_5_3"
        if "domain" in lname:
            return "falsifier_domain"
        if "situation" in lname or "scenario" in lname or "context" in lname:
            return "falsifier_situation"
        if "override" in lname or "interaction" in lname:
            return {}
        if "policy" in lname:
            return {}

